// Microsoft Kalender, persoenlich je Person.
//
// Der Zugang wird ueber das Feld caller nachgeschlagen. Dieses Feld setzt der
// MCP-Client des Agenten und ueberschreibt dabei, was das Modell geschickt hat.
// Kommt es leer an (Sub-Agent, Hintergrundlauf), verweigert der Skill, statt zu
// raten. Das ist Absicht: lieber keine Antwort als die Termine der falschen Person.

const input = { ...$input.first().json };
// Leere Werte zaehlen als nicht gesetzt: n8n veroeffentlicht jedes deklarierte
// Feld als Pflichtfeld, der Aufrufer fuellt fehlende deshalb mit "" auf.
for (const _k of Object.keys(input)) { if (input[_k] === '' || input[_k] === null) delete input[_k]; }

const action = input.action || '';
const caller = String(input.caller || '').trim();

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pg = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };
const GRAPH = 'https://graph.microsoft.com/v1.0';

function fail(msg) { return [{ json: { error: msg } }]; }

const credRows = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.microsoft&select=cred_key,cred_value',
  headers: pg, json: true
});
const cred = {};
for (const c of (credRows || [])) cred[c.cred_key] = c.cred_value;
for (const need of ['tenant_id', 'client_id', 'client_secret', 'token_key', 'redirect_uri']) {
  if (!cred[need]) return fail('Microsoft ist nicht eingerichtet, es fehlt: ' + need);
}
const connectUrl = String(cred.redirect_uri).replace('ms-oauth-callback', 'ms-connect');

if (!caller) {
  return fail('Kein Nutzerbezug vorhanden. Kalenderzugriff geht nur im Namen einer angemeldeten Person, nicht aus einem Hintergrundlauf oder einem Sub-Agenten.');
}

// Die fragende Person kommt als Anmeldekennung (web:gretel) oder bereits als
// Entra-Kennung. Der Zugang haengt immer an der Entra-Kennung, deshalb hier
// aufloesen. Findet sich nichts, bleibt es bei der urspruenglichen Kennung und
// der Skill meldet sauber "noch kein Konto verbunden".
let personKey = caller;
if (!caller.startsWith('entra:')) {
  try {
    const map = await helpers.httpRequest({
      method: 'GET',
      url: SUPABASE_URL + '/rest/v1/user_identity_map?legacy_key=eq.' + encodeURIComponent(caller) + '&select=entra_key',
      headers: pg, json: true
    });
    if (map && map[0] && map[0].entra_key) personKey = map[0].entra_key;
  } catch (e) {}
}

// ---- Zugang holen, bei Bedarf erneuern -------------------------------------
async function accessToken() {
  const rows = await helpers.httpRequest({
    method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/get_user_token', headers: pg, json: true,
    body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_key: cred.token_key })
  });
  const row = rows && rows[0];
  if (!row) {
    return { error: 'Fuer diese Person ist noch kein Microsoft-Konto verbunden. Einmalig verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  }
  if (row.status !== 'connected') {
    return { error: 'Die Verbindung zum Microsoft-Konto ist unterbrochen (' + row.status + '). Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  }
  const restMs = new Date(row.expires_at).getTime() - Date.now();
  if (restMs > 5 * 60 * 1000) return { token: row.access_token };

  // Erneuern. Faellt das durch, ist der Zugang zu Ende und die Person muss neu
  // verbinden. Das wird vermerkt, damit es nicht bei jedem Aufruf neu auffaellt.
  if (!row.refresh_token) {
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/mark_user_token', headers: pg,
      body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_status: 'reconnect_required', p_detail: 'kein refresh_token vorhanden' }) });
    return { error: 'Der Zugang ist abgelaufen und laesst sich nicht erneuern. Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  }
  let tok;
  try {
    tok = await helpers.httpRequest({
      method: 'POST',
      url: 'https://login.microsoftonline.com/' + encodeURIComponent(cred.tenant_id) + '/oauth2/v2.0/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, json: true,
      body: 'client_id=' + encodeURIComponent(cred.client_id) +
            '&client_secret=' + encodeURIComponent(cred.client_secret) +
            '&refresh_token=' + encodeURIComponent(row.refresh_token) +
            '&grant_type=refresh_token' +
            '&scope=' + encodeURIComponent(row.scopes || 'openid profile offline_access Calendars.ReadWrite MailboxSettings.Read')
    });
  } catch (e) {
    const body = (e && e.response && e.response.body) ? JSON.stringify(e.response.body) : String(e.message || e);
    const code = (body.match(/AADSTS\d+/) || ['unbekannt'])[0];
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/mark_user_token', headers: pg,
      body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_status: 'reconnect_required', p_detail: code }) });
    return { error: 'Die Verbindung zum Microsoft-Konto ist beendet (' + code + '). Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  }
  await helpers.httpRequest({
    method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/upsert_user_token', headers: pg,
    body: JSON.stringify({
      p_user_key: personKey, p_provider: 'microsoft', p_key: cred.token_key,
      p_access_token: tok.access_token, p_refresh_token: tok.refresh_token || '',
      p_expires_at: new Date(Date.now() + ((tok.expires_in || 3600) * 1000)).toISOString(),
      p_scopes: tok.scope || row.scopes || null, p_account_id: row.account_id || ''
    })
  });
  return { token: tok.access_token };
}

const t = await accessToken();
if (t.error) return fail(t.error);
const H = { Authorization: 'Bearer ' + t.token, 'Content-Type': 'application/json' };

// Zeitzone der Person: ohne sie entstehen Termine in UTC, und niemand merkt es,
// bis jemand zwei Stunden zu frueh im Besprechungsraum sitzt.
let tz = 'W. Europe Standard Time';
try {
  const ms = await helpers.httpRequest({ method: 'GET', url: GRAPH + '/me/mailboxSettings', headers: H, json: true });
  if (ms && ms.timeZone) tz = ms.timeZone;
} catch (e) {}
const HZ = Object.assign({}, H, { Prefer: 'outlook.timezone="' + tz + '"' });

// Zeitangaben mit Offset (Z, +02:00) kommen vom Modell regelmaessig. Graph
// bekaeme dann Offset UND Zeitzone und rechnet doppelt: 09:00+02:00 landete am
// 03.09.2026 als 07:00 im Kalender. Deshalb: mit Offset nach UTC wandeln und als
// UTC schicken, ohne Offset unveraendert als Wandzeit in der Postfach-Zeitzone.
// Die Antwort kommt ueber den Prefer-Header ohnehin in der Postfach-Zeitzone.
function zeit(s) {
  const v = String(s || '').trim();
  if (/T.*(Z|[+-]\d{2}:?\d{2})$/i.test(v)) {
    const dt = new Date(v);
    if (!isNaN(dt.getTime())) return { dateTime: dt.toISOString().slice(0, 19), timeZone: 'UTC' };
  }
  return { dateTime: v, timeZone: tz };
}
// Minuten auf eine Wandzeit ohne Offset addieren (Rechnen in UTC ist hier nur
// ein Trick, die Zone bleibt die des Eingabewerts).
function plusMinuten(naiv, min) {
  const dt = new Date(String(naiv).slice(0, 19) + 'Z');
  return new Date(dt.getTime() + min * 60000).toISOString().slice(0, 19);
}
function dauerMinuten(ev) {
  const a = new Date(String(ev.start.dateTime).slice(0, 19) + 'Z');
  const b = new Date(String(ev.end.dateTime).slice(0, 19) + 'Z');
  const m = Math.round((b - a) / 60000);
  return (isNaN(m) || m <= 0) ? 30 : m;
}
// Teilnehmende: nur echte Adressen. Ein Name ohne @ wurde frueher still
// verworfen, der Termin entstand "ohne Teilnehmende" und niemand merkte es.
function teilnehmerParsen(roh) {
  const teile = String(roh || '').split(/[,;]+/).map(x => x.trim()).filter(Boolean)
    .flatMap(x => (/\s/.test(x) && x.split(/\s+/).every(t => t.includes('@'))) ? x.split(/\s+/) : [x]);
  const ohne = teile.filter(x => !x.includes('@'));
  if (ohne.length) return { fehler: 'Keine E-Mail-Adresse: ' + ohne.join(', ') + '. Teilnehmende brauchen eine vollstaendige Adresse, sonst bekommt niemand eine Einladung. Bitte die Adresse nachschlagen oder nachfragen, nicht raten.' };
  return { adressen: teile };
}
// Termin frisch lesen: nur GET ehrt Prefer: outlook.timezone, POST und PATCH nicht.
async function nachlesen(id) {
  return helpers.httpRequest({ method: 'GET', url: GRAPH + '/me/events/' + encodeURIComponent(id) + '?$select=id,subject,start,end,attendees,location', headers: HZ, json: true });
}
// confirm ist der Name, confirm_invites wird aus Kompatibilitaet weiter angenommen.
function bestaetigt(inp) { return String(inp.confirm || inp.confirm_invites || '').toLowerCase() === 'true'; }

function errText(e) {
  const b = e && e.response && e.response.body;
  if (b && b.error && b.error.message) return b.error.message;
  return String((e && e.message) || e);
}
function fmt(ev) {
  const s = (ev.start && ev.start.dateTime || '').replace('T', ' ').slice(0, 16);
  const e = (ev.end && ev.end.dateTime || '').replace('T', ' ').slice(11, 16);
  const wer = (ev.attendees || []).map(a => (a.emailAddress || {}).name).filter(Boolean).join(', ');
  return '- ' + s + ' bis ' + e + '  ' + (ev.subject || '(ohne Betreff)') +
         (ev.location && ev.location.displayName ? '  [' + ev.location.displayName + ']' : '') +
         (wer ? '  mit ' + wer : '') + '  (id: ' + ev.id + ')';
}

try {
  if (action === 'list_events') {
    const von = input.start || new Date().toISOString();
    const bis = input.end || new Date(Date.now() + 7 * 864e5).toISOString();
    const limit = Math.min(parseInt(input.limit || '25', 10) || 25, 50);
    const url = GRAPH + '/me/calendarView?startDateTime=' + encodeURIComponent(von) +
      '&endDateTime=' + encodeURIComponent(bis) +
      '&$orderby=start/dateTime&$top=' + limit +
      '&$select=id,subject,start,end,location,attendees,isAllDay';
    const r = await helpers.httpRequest({ method: 'GET', url, headers: HZ, json: true });
    const evs = (r && r.value) || [];
    if (!evs.length) return [{ json: { result: 'Keine Termine zwischen ' + von.slice(0, 10) + ' und ' + bis.slice(0, 10) + '.' } }];
    return [{ json: { result: evs.length + ' Termine (Zeitzone ' + tz + '):\n' + evs.map(fmt).join('\n') } }];
  }

  if (action === 'find_free_slots') {
    const von = input.start; const bis = input.end;
    if (!von || !bis) return fail('Parameter "start" und "end" sind noetig, im Format 2026-08-07T08:00:00.');
    const dauer = Math.max(parseInt(input.duration_min || '30', 10) || 30, 5);
    const r = await helpers.httpRequest({
      method: 'POST', url: GRAPH + '/me/calendar/getSchedule', headers: HZ, json: true,
      body: JSON.stringify({
        schedules: [input.for_email || 'me'].filter(x => x !== 'me').length ? [input.for_email] : [(await helpers.httpRequest({ method: 'GET', url: GRAPH + '/me', headers: H, json: true })).userPrincipalName],
        startTime: zeit(von),
        endTime: zeit(bis),
        availabilityViewInterval: dauer
      })
    });
    const view = ((r && r.value && r.value[0]) || {}).availabilityView || '';
    if (!view) return fail('Microsoft lieferte keine Belegung zurueck.');
    const frei = [];
    const startMs = new Date(von).getTime();
    for (let i = 0; i < view.length; i++) {
      if (view[i] === '0') {
        const a = new Date(startMs + i * dauer * 60000);
        frei.push(a.toISOString().replace('T', ' ').slice(0, 16));
      }
    }
    if (!frei.length) return [{ json: { result: 'Keine freien Zeitfenster von ' + dauer + ' Minuten in diesem Zeitraum.' } }];
    return [{ json: { result: frei.length + ' freie Fenster zu je ' + dauer + ' Minuten (Zeitzone ' + tz + '), Beginn jeweils:\n' + frei.slice(0, 40).map(x => '- ' + x).join('\n') + (frei.length > 40 ? '\n... (' + frei.length + ' insgesamt)' : '') } }];
  }

  if (action === 'create_event') {
    if (!input.subject || !input.start || !input.end) return fail('Fuer einen Termin brauche ich "subject", "start" und "end" (Format 2026-08-07T10:00:00).');
    const tn = teilnehmerParsen(input.attendees);
    if (tn.fehler) return fail(tn.fehler);
    const teilnehmer = tn.adressen;
    // Ein Termin mit Teilnehmenden verschickt Einladungen aus dem Postfach der
    // Person. Bei externen Adressen deshalb nur mit ausdruecklicher Bestaetigung.
    const extern = teilnehmer.filter(a => !a.toLowerCase().endsWith(String(cred.internal_domain || '').toLowerCase()) || !cred.internal_domain);
    if (teilnehmer.length && extern.length && !bestaetigt(input)) {
      return fail('Dieser Termin wuerde Einladungen an ' + teilnehmer.join(', ') + ' verschicken. Wenn das so gewollt ist, bitte mit confirm=true erneut aufrufen.');
    }
    const body = {
      subject: input.subject,
      start: zeit(input.start),
      end: zeit(input.end)
    };
    if (input.body) body.body = { contentType: 'text', content: input.body };
    if (input.location) body.location = { displayName: input.location };
    if (teilnehmer.length) body.attendees = teilnehmer.map(a => ({ emailAddress: { address: a }, type: 'required' }));
    const angelegt = await helpers.httpRequest({ method: 'POST', url: GRAPH + '/me/events', headers: HZ, json: true, body: JSON.stringify(body) });
    // Die Antwort auf POST und PATCH ignoriert den Prefer-Header und kommt in der
    // Zone der Anfrage zurueck (bei UTC-Eingabe also 07:00 statt 09:00). Deshalb
    // den Termin noch einmal lesen, GET liefert ihn in der Postfach-Zeitzone.
    const r = await nachlesen(angelegt.id);
    return [{ json: { result: 'Termin angelegt: "' + r.subject + '" am ' + String(r.start.dateTime).replace('T', ' ').slice(0, 16) +
      ' bis ' + String(r.end.dateTime).slice(11, 16) + ' (Zeitzone ' + tz + ')' +
      (teilnehmer.length ? ', Einladung an ' + teilnehmer.join(', ') : ', ohne Teilnehmende') + ' (id: ' + r.id + ')' } }];
  }

  if (action === 'update_event') {
    if (!input.event_id) return fail('Parameter "event_id" ist noetig. Die id steht bei jedem Termin aus list_events dabei.');
    const vorher = await helpers.httpRequest({ method: 'GET', url: GRAPH + '/me/events/' + encodeURIComponent(input.event_id) + '?$select=subject,start,end,attendees,location', headers: HZ, json: true });
    const patch = {};
    if (input.subject) patch.subject = input.subject;
    if (input.location) patch.location = { displayName: input.location };
    if (input.body) patch.body = { contentType: 'text', content: input.body };
    // Verschieben: wird nur der Beginn genannt, bleibt die Dauer erhalten, wird
    // nur das Ende genannt, bleibt der Beginn. Beide Werte gehen immer zusammen
    // an Graph, sonst entsteht ein Termin, der vor seinem Anfang endet.
    if (input.start || input.end) {
      const dauer = dauerMinuten(vorher);
      let s = input.start ? zeit(input.start) : null;
      let e = input.end ? zeit(input.end) : null;
      if (s && !e) e = { dateTime: plusMinuten(s.dateTime, dauer), timeZone: s.timeZone };
      if (e && !s) s = { dateTime: plusMinuten(e.dateTime, -dauer), timeZone: e.timeZone };
      if (new Date(e.dateTime + 'Z') <= new Date(s.dateTime + 'Z') && s.timeZone === e.timeZone) return fail('Das Ende liegt nicht nach dem Beginn.');
      patch.start = s; patch.end = e;
    }
    let neue = [];
    if (input.attendees) {
      const tn = teilnehmerParsen(input.attendees);
      if (tn.fehler) return fail(tn.fehler);
      const vorhanden = (vorher.attendees || []).map(a => ((a.emailAddress || {}).address || '').toLowerCase());
      neue = tn.adressen.filter(a => !vorhanden.includes(a.toLowerCase()));
      if (neue.length) patch.attendees = (vorher.attendees || []).concat(neue.map(a => ({ emailAddress: { address: a }, type: 'required' })));
    }
    if (!Object.keys(patch).length) return fail('Nichts zu aendern: subject, start, end, location, body oder attendees angeben.');
    const hatGaeste = ((vorher.attendees || []).length > 0) || neue.length > 0;
    if (hatGaeste && !bestaetigt(input)) {
      return fail('Der Termin "' + vorher.subject + '" hat Teilnehmende, Microsoft schickt ihnen die Aenderung als Aktualisierung. Wenn das gewollt ist, bitte mit confirm=true erneut aufrufen.');
    }
    await helpers.httpRequest({ method: 'PATCH', url: GRAPH + '/me/events/' + encodeURIComponent(input.event_id), headers: HZ, json: true, body: JSON.stringify(patch) });
    const r = await nachlesen(input.event_id);
    const geaendert = Object.keys(patch).map(k => ({ subject: 'Betreff', start: 'Beginn', end: 'Ende', location: 'Ort', body: 'Beschreibung', attendees: 'Teilnehmende' })[k] || k);
    return [{ json: { result: 'Termin aktualisiert (' + geaendert.join(', ') + '): "' + r.subject + '" am ' + String(r.start.dateTime).replace('T', ' ').slice(0, 16) +
      ' bis ' + String(r.end.dateTime).slice(11, 16) + ' (Zeitzone ' + tz + ')' +
      (hatGaeste ? ', die Teilnehmenden wurden benachrichtigt' : '') +
      (neue.length ? ', neu eingeladen: ' + neue.join(', ') : '') + ' (id: ' + r.id + ')' } }];
  }

  if (action === 'cancel_event') {
    if (!input.event_id) return fail('Parameter "event_id" ist noetig. Die id steht bei jedem Termin aus list_events dabei.');
    const vorher = await helpers.httpRequest({ method: 'GET', url: GRAPH + '/me/events/' + encodeURIComponent(input.event_id) + '?$select=subject,start,attendees', headers: HZ, json: true });
    const hatGaeste = ((vorher.attendees || []).length > 0);
    if (hatGaeste && String(input.confirm || '').toLowerCase() !== 'true') {
      return fail('Der Termin "' + vorher.subject + '" hat Teilnehmende, eine Absage geht als Nachricht an sie raus. Wenn das gewollt ist, bitte mit confirm=true erneut aufrufen.');
    }
    if (hatGaeste) {
      await helpers.httpRequest({ method: 'POST', url: GRAPH + '/me/events/' + encodeURIComponent(input.event_id) + '/cancel', headers: H, json: true, body: JSON.stringify({ comment: input.comment || '' }) });
    } else {
      await helpers.httpRequest({ method: 'DELETE', url: GRAPH + '/me/events/' + encodeURIComponent(input.event_id), headers: H });
    }
    return [{ json: { result: 'Termin "' + vorher.subject + '" ' + (hatGaeste ? 'abgesagt, die Teilnehmenden wurden benachrichtigt.' : 'geloescht.') } }];
  }

  return fail('Unbekannte Aktion "' + action + '". Moeglich sind: list_events, find_free_slots, create_event, update_event, cancel_event.');
} catch (e) {
  return fail('Microsoft Kalender (' + action + '): ' + errText(e));
}
